    """The text of the reviewer's final report in a transcript JSONL.

    THE LAST PLAIN TEXT BLOCK IS THE WRONG THING TO READ. In this harness a subagent's
    final report is delivered through a `SubagentHandback` TOOL CALL, not as trailing
    assistant prose -- a real reviewer transcript inspected during this feature's own
    adversarial review carried its whole findings report inside a `SubagentHandback`
    tool_use's `input.message`, followed by a separate, shorter plain-text turn
    ("I've sent the full adversarial pass ... back to the orchestrating session") that a
    last-text-block reader would return instead. The LAST `SubagentHandback` call in the
    transcript is preferred; only if none exists does this fall back to the last plain
    text block, for a reviewer run without that tool.
    """
    last_text, last_handback = "", None
    with open(path, encoding="utf-8") as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            try:
                rec = json.loads(line)
            except json.JSONDecodeError:
                continue
            if rec.get("type") != "assistant":
                continue
            msg = rec.get("message")
            if not isinstance(msg, dict):
                continue
            content = msg.get("content")
            if isinstance(content, str):
