import sys, sqlite3
sys.path.insert(0, "scripts/research"); sys.path.insert(0, "scripts")
import retrieval_log as rl
import dbcore

con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
con.row_factory = sqlite3.Row

derived_mined_ref = {
    68:'REF-00977', 69:'REF-00984', 70:'REF-00985', 73:'REF-00979', 74:'REF-00980',
    75:'REF-00983', 76:'REF-00986', 88:'REF-01005', 95:'REF-01007', 97:'REF-01008',
    99:'REF-01006',
}
sessions = sorted(p.name for p in rl.LOG_ROOT.iterdir() if p.is_dir())
links_by_exec = {}
for session in sessions:
    execs = con.execute(
        "select exec_id, query_text from search_executions "
        "where created_by_session in (?, ?)", [session, session + ".md"]).fetchall()
    if not execs:
        continue
    recs = rl._manifest_records(session)
    artefacts = sorted({r.get("artefact") for r in recs if r.get("artefact")})
    for art in artefacts:
        rel_path = f"retrieval-log/{session}/{art}"
        matches = []
        for e in execs:
            mined = derived_mined_ref.get(e["exec_id"])
            try:
                if mined:
                    rl.check_artefact_link(rel_path, mined_ref_id=mined)
                else:
                    rl.check_artefact_link(rel_path, query_text=e["query_text"])
                matches.append(e["exec_id"])
            except ValueError:
                continue
        if len(matches) == 1:
            links_by_exec.setdefault(matches[0], []).append(rel_path)

candidates = con.execute(
    "select candidate_id, exec_id, locator, surfaced_in from search_candidates "
    "where exec_id is not null and surfaced_in is null").fetchall()
found = []
for c in candidates:
    doi = dbcore.single_doi_in(c["locator"])
    if not doi:
        continue
    artefacts = links_by_exec.get(c["exec_id"], [])
    for art in artefacts:
        try:
            raw = rl.read_artefact_bytes(art)
            text, enc = rl.decode_artefact(raw)
            if text and rl.normalise_quote(doi) in rl.normalise_quote(text):
                found.append((c["candidate_id"], c["exec_id"], doi, art))
                break
        except Exception:
            continue

print(f"candidates checked with a DOI + a linked exec artefact: {sum(1 for c in candidates if dbcore.single_doi_in(c['locator']) and links_by_exec.get(c['exec_id']))}")
print(f"additional surfaced_in-derivable candidates found: {len(found)}")
for f in found:
    print("  ", f)
PY

